def zeta(s, max_iter=100):
    if s == 1:
        return float('inf')
    result = 0
    for n in range(1, max_iter + 1):
        term = 1 / (n ** s)
        if abs(term) < 1e-10:
            break
        result += term
    return result

def find_zero(length):
    low, high = 0, length
    while low <= high:
        mid = (low + high) / 2
        z = zeta(1/2 + 1j * mid)
        if abs(z) < 1e-10:
            return mid
        elif z.real > 0:
            high = mid - 1
        else:
            low = mid + 1
    return None

def generate_cnf(n):
    clauses = []
    for _ in range(n):
        clause = random.sample(range(1, n+1), 2)
        clauses.append(clause)
    cnf = [clauses]
    return cnf

def resolution_length(cnf):
    # Simplified resolution algorithm to estimate length
    steps = 0
    while True:
        new_clauses = []
        for clause in cnf:
            if len(clause) == 1:
                return steps
            for other_clause in cnf:
                if set(clause).isdisjoint(other_clause):
                    continue
                diff = list(set(clause) ^ set(other_clause))
                if len(diff) == 2:
                    new_clauses.append(diff)
        cnf.extend(new_clauses)
        steps += 1

